COMMENT ON TABLE TB_TRD_INVOICE_ITEM IS '인보이스 품목(Packing List)';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.INV_MGMT_NO IS '인보이스 관리번호';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.LINE_NO IS '라인';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.MARKS_PKG IS 'Marks & No of PKG';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.GOODS_DESC IS '품명';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.HS_CODE IS 'HS Code';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.QTY IS '수량 - 정수';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.UNIT IS '단위';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.UNIT_PRICE IS '단가';
COMMENT ON COLUMN TB_TRD_INVOICE_ITEM.LINE_AMT IS '금액 - = QTY × UNIT_PRICE';

-- Bill of Entry(수입신고) : IDPMS 수신분 + 수기등록분. Invoice 탭 정보 자동복사(기존 요청). 복수 송금으로 분할결제 → 잔액관리.
CREATE TABLE TB_TRD_BOE (
  BOE_MGMT_NO              VARCHAR2(16) NOT NULL,
