  BOE_DT                   DATE NOT NULL,
  PORT_CODE                VARCHAR2(6) NOT NULL,
  BOE_TYPE                 VARCHAR2(1) NOT NULL,
  CUST_NO                  VARCHAR2(8) NOT NULL,
  IEC_NO                   VARCHAR2(10) NOT NULL,
  AD_CODE                  VARCHAR2(14),
