COMMENT ON COLUMN TB_IF_EDPMS_OUT.ERR_MSG IS '오류';

-- CIMS 보고 헤더 : RBI CIMS 제출 회차 관리(LRS 일일, R-Return, SRVA 등).
CREATE TABLE TB_CIMS_RETURN (
