COMMENT ON TABLE TB_CIMS_RETURN IS 'CIMS 보고 헤더';
COMMENT ON COLUMN TB_CIMS_RETURN.RETURN_ID IS '회차ID';
COMMENT ON COLUMN TB_CIMS_RETURN.RETURN_CODE IS '리턴코드 - LRS_DAILY/R_RETURN/SRVA/ODI 등(RBI 리턴명세 기준)';
COMMENT ON COLUMN TB_CIMS_RETURN.PERIOD_FROM IS '대상기간 시작';
COMMENT ON COLUMN TB_CIMS_RETURN.PERIOD_TO IS '대상기간 종료';
COMMENT ON COLUMN TB_CIMS_RETURN.DUE_DT IS '제출기한';
COMMENT ON COLUMN TB_CIMS_RETURN.REC_CNT IS '레코드수';
COMMENT ON COLUMN TB_CIMS_RETURN.FILE_NAME IS '파일명 - XML/XBRL/CSV - 리턴명세';
COMMENT ON COLUMN TB_CIMS_RETURN.SUBMIT_TS IS '제출일시';
COMMENT ON COLUMN TB_CIMS_RETURN.ACK_NO IS 'RBI 접수번호';
COMMENT ON COLUMN TB_CIMS_RETURN.RETURN_STS IS '상태 - GEN/VAL/SUBM/ACK/REJ/RESB';
COMMENT ON COLUMN TB_CIMS_RETURN.REJ_REASON IS '반려사유';
COMMENT ON COLUMN TB_CIMS_RETURN.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_CIMS_RETURN.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_CIMS_RETURN.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_CIMS_RETURN.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_CIMS_RETURN.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- CIMS 보고 상세 : 회차별 포함 거래 키 - 재제출/정정 추적.
CREATE TABLE TB_CIMS_RETURN_DTL (
