  CLAIM_REF                VARCHAR2(16) NOT NULL,
  CLAIMING_BIC             VARCHAR2(11) NOT NULL,
  CLAIM_AMT                NUMBER(18,2) NOT NULL,
  CLAIM_CHG                NUMBER(18,2),
  RCV_DT                   DATE NOT NULL,
  PAY_DUE_DT               DATE NOT NULL,
  REQ_VALUE_DT             DATE,
  PAY_VALUE_DT             DATE,
  PAY_METHOD               VARCHAR2(6),
  PAY_MSG_ID               VARCHAR2(20),
  HO_CUST_SETTLE_DT        DATE,
  IO_REF                   VARCHAR2(16),
  CLAIM_STS                VARCHAR2(4) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_RA_CLAIM PRIMARY KEY (CLAIM_ID)
);
COMMENT ON TABLE TB_RA_CLAIM IS '상환청구·대지급';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_ID IS '청구ID';
COMMENT ON COLUMN TB_RA_CLAIM.RA_NO IS 'RA 번호';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_REF IS '청구은행 Ref';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIMING_BIC IS '청구은행';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_AMT IS '청구금액 - ≤ AVAIL_AMT';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_CHG IS '청구은행 수수료';
COMMENT ON COLUMN TB_RA_CLAIM.RCV_DT IS '접수일';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_DUE_DT IS '지급기한 - 접수일 + 3 인도 영업일 (CAL IN)';
COMMENT ON COLUMN TB_RA_CLAIM.REQ_VALUE_DT IS '청구 결제일';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_VALUE_DT IS '실제 결제일 - 통화국 영업일(USD→US, INR→IN)';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_METHOD IS '지급방식 - PACS009/RTGS/VOSTRO';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_MSG_ID IS '지급 메시지';
COMMENT ON COLUMN TB_RA_CLAIM.HO_CUST_SETTLE_DT IS '본점 고객 결제일 - 본점 통보(MT756/MT799/정산파일)';
COMMENT ON COLUMN TB_RA_CLAIM.IO_REF IS '본지점 거래 Ref';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_STS IS '상태 - RCVD/CHKD/PAID/REJ(불일치·수권초과)';
COMMENT ON COLUMN TB_RA_CLAIM.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_RA_CLAIM.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_RA_CLAIM.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_RA_CLAIM.UPD_TS IS '수정일시';
