CREATE INDEX IX_RA_CLAIM_2 ON TB_RA_CLAIM (PAY_DUE_DT);

-- 본지점 거래(미정산 원장) : 본점과의 채권·채무 건별 원장. 정산배치로 묶여 SETTLED 처리.
CREATE TABLE TB_IO_TXN (
  IO_REF                   VARCHAR2(16) NOT NULL,
  IO_FUND                  VARCHAR2(4) NOT NULL,
  IO_ITEM                  VARCHAR2(6) NOT NULL,
  SRC_TABLE                VARCHAR2(30) NOT NULL,
  SRC_KEY                  VARCHAR2(40) NOT NULL,
  CCY                      VARCHAR2(3) NOT NULL,
  AMT                      NUMBER(18,2) NOT NULL,
  DC                       VARCHAR2(3) NOT NULL,
  BR_VALUE_DT              DATE NOT NULL,
  HO_VALUE_DT              DATE,
  FLOAT_DAYS               NUMBER(4),
  SETTLE_STS               VARCHAR2(7) NOT NULL,
  BATCH_ID                 VARCHAR2(16),
  SETTLED_AMT              NUMBER(18,2) NOT NULL,
  SETTLED_DT               DATE,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_IO_TXN PRIMARY KEY (IO_REF)
);
COMMENT ON TABLE TB_IO_TXN IS '본지점 거래(미정산 원장)';
COMMENT ON COLUMN TB_IO_TXN.IO_REF IS '본지점 Ref';
COMMENT ON COLUMN TB_IO_TXN.IO_FUND IS '기금 구분 - GAP/EULA/EULB. GAP은 이자·정산배치 제외';
COMMENT ON COLUMN TB_IO_TXN.IO_ITEM IS '거래유형 - CODE:IO_ITEM';
COMMENT ON COLUMN TB_IO_TXN.SRC_TABLE IS '원천 - TB_RA_CLAIM/TB_FX_REMIT_MST/TB_SWIFT_MSG';
COMMENT ON COLUMN TB_IO_TXN.SRC_KEY IS '원천키';
COMMENT ON COLUMN TB_IO_TXN.CCY IS '통화';
COMMENT ON COLUMN TB_IO_TXN.AMT IS '금액';
COMMENT ON COLUMN TB_IO_TXN.DC IS '채권/채무 - DFH(Due from HO 채권)/DTH(Due to HO 채무)';
COMMENT ON COLUMN TB_IO_TXN.BR_VALUE_DT IS '지점 결제일';
COMMENT ON COLUMN TB_IO_TXN.HO_VALUE_DT IS '본점 결제일 - 본점 고객 결제·본점 기장일';
COMMENT ON COLUMN TB_IO_TXN.FLOAT_DAYS IS '일수 차이 - = BR_VALUE_DT - HO_VALUE_DT (±)';
COMMENT ON COLUMN TB_IO_TXN.SETTLE_STS IS '정산상태 - CODE:IO_SETTLE';
COMMENT ON COLUMN TB_IO_TXN.BATCH_ID IS '정산배치';
COMMENT ON COLUMN TB_IO_TXN.SETTLED_AMT IS '정산액';
COMMENT ON COLUMN TB_IO_TXN.SETTLED_DT IS '정산일';
COMMENT ON COLUMN TB_IO_TXN.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_IO_TXN.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_IO_TXN.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_IO_TXN.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_IO_TXN.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_IO_TXN_1 ON TB_IO_TXN (SETTLE_STS,CCY);
CREATE INDEX IX_IO_TXN_2 ON TB_IO_TXN (BATCH_ID);

-- 본지점 정산 규칙 : 통화·거래유형별 정산주기와 자동정산 트리거.
CREATE TABLE TB_IO_SETTLE_RULE (
  CCY                      VARCHAR2(3) NOT NULL,
