  CONSTRAINT PK_IO_SETTLE_RULE PRIMARY KEY (CCY, IO_ITEM)
);
COMMENT ON TABLE TB_IO_SETTLE_RULE IS '본지점 정산 규칙';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.CCY IS '통화';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.IO_ITEM IS '거래유형 - ALL 허용';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.CYCLE IS '주기 - D/W-FRI/M-EOM';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.CUTOFF_TIME IS '마감시각 - IST, 이후 건은 다음 회차';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.TRIG_CNT IS '건수 트리거';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.TRIG_AMT_USD IS '금액 트리거';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.NETTING_YN IS '상계 여부 - 통화별 DFH-DTH 상계';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.SETTLE_CCY IS '정산통화 - 원통화 또는 USD 환산정산';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.SETTLE_METHOD IS '정산방식 - PACS009(본점 지급)/NOSTRO(본점 계좌 차기·MT900·camt.054)';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_IO_SETTLE_RULE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 본지점 정산배치 : 주기·트리거별 정산 회차. 어디까지 정산했는지는 CUTOFF_TS 기준으로 판단.
CREATE TABLE TB_IO_SETTLE_BATCH (
