);
COMMENT ON TABLE TB_IO_SETTLE_BATCH IS '본지점 정산배치';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.BATCH_ID IS '배치ID';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.CCY IS '통화';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.TRIGGER IS '트리거 - CYCLE/CNT/AMT/MANU';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.CUTOFF_TS IS '포함 기준시각 - 이 시각까지 기장된 OPEN 건 포함';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.ITEM_CNT IS '건수';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.GROSS_DFH IS '채권 합계';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.GROSS_DTH IS '채무 합계';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.NET_AMT IS '순액 - + 본점이 지급 / - 지점이 지급';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.FLOAT_INT_AMT IS '휴일차이 이자(정산분) - SETTLE 처리분 합계';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.FX_BASE_RATE IS '기준환율 - 환산정산 시';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.FX_SPREAD_BP IS '스프레드(bp)';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.SETTLE_RATE IS '적용환율 - = 기준 ± 스프레드';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.STMT_MSG_ID IS '정산내역 통지 - MT950/MT999 또는 정산파일';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.SETTLE_MSG_ID IS '정산 자금 메시지 - pacs.009 수신 / camt.054(MT910)';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.BATCH_STS IS '상태 - OPEN/SENT/PAID/PART/DISP';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.PAID_DT IS '본점 입금일';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_IO_SETTLE_BATCH.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 본지점 기준환율·금리 : 통화간 기준환율+스프레드, 통화별 기준금리+스프레드. 유효기간 이력.
CREATE TABLE TB_IO_RATE (
  RATE_KIND                VARCHAR2(3) NOT NULL,
