  EFF_FROM_DT              DATE NOT NULL,
  EFF_TO_DT                DATE NOT NULL,
  BASE_SRC                 VARCHAR2(20) NOT NULL,
  BASE_RATE                NUMBER(15,6) NOT NULL,
  SPREAD_BP                NUMBER(6,2) NOT NULL,
  PREF_SPREAD_BP           NUMBER(6,2),
  ALL_IN                   NUMBER(15,6) NOT NULL,
  DAYCOUNT                 VARCHAR2(8),
  APPROVED_BY              VARCHAR2(10) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_IO_RATE PRIMARY KEY (RATE_KIND, IO_FUND, CCY_KEY, TENOR, EFF_FROM_DT)
);
COMMENT ON TABLE TB_IO_RATE IS '본지점 기준환율·금리';
COMMENT ON COLUMN TB_IO_RATE.RATE_KIND IS '구분 - FX/INT';
COMMENT ON COLUMN TB_IO_RATE.IO_FUND IS '기금 구분 - FX는 ALL, INT는 EULA/EULB (GAP은 행 없음 = 0%)';
COMMENT ON COLUMN TB_IO_RATE.CCY_KEY IS '통화(쌍) - FX: USD/INR · INT: USD';
COMMENT ON COLUMN TB_IO_RATE.TENOR IS '기간구간 - EULB만 사용(T007~T999), 그 외 ''-''';
COMMENT ON COLUMN TB_IO_RATE.EFF_FROM_DT IS '적용시작';
COMMENT ON COLUMN TB_IO_RATE.EFF_TO_DT IS '적용종료';
COMMENT ON COLUMN TB_IO_RATE.BASE_SRC IS '기준 출처 - FX: FBIL/RBI Ref·본점 고시 / INT: SOFR·MIBOR·KOFR';
COMMENT ON COLUMN TB_IO_RATE.BASE_RATE IS '기준값';
COMMENT ON COLUMN TB_IO_RATE.SPREAD_BP IS '스프레드(bp) - FX: 환율 대비 bp / INT: 금리 가산 bp (을B는 표준)';
COMMENT ON COLUMN TB_IO_RATE.PREF_SPREAD_BP IS '우대 스프레드(bp) - 을B 우대조건 충족 시';
COMMENT ON COLUMN TB_IO_RATE.ALL_IN IS '적용값';
COMMENT ON COLUMN TB_IO_RATE.DAYCOUNT IS '일수계산 - ACT/360·ACT/365 (INT)';
COMMENT ON COLUMN TB_IO_RATE.APPROVED_BY IS '승인(본점 자금부)';
COMMENT ON COLUMN TB_IO_RATE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_IO_RATE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_IO_RATE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_IO_RATE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_IO_RATE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 본지점 을B 자금거래 : 본점 차입·예치(여신성). 기간구간 금리 + 우대조건 판정, 만기·이자 관리, MT320 확인.
