  ROLLOVER_OF              VARCHAR2(16),
  FUND_STS                 VARCHAR2(4) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_IO_FUNDING PRIMARY KEY (FUND_ID)
);
COMMENT ON TABLE TB_IO_FUNDING IS '본지점 을B 자금거래';
COMMENT ON COLUMN TB_IO_FUNDING.FUND_ID IS '자금거래ID';
COMMENT ON COLUMN TB_IO_FUNDING.DIRECTION IS '방향 - BORROW 본점차입 / PLACE 본점예치';
COMMENT ON COLUMN TB_IO_FUNDING.PURPOSE IS '용도 - 여신 재원·유동성 등';
COMMENT ON COLUMN TB_IO_FUNDING.CCY IS '통화';
COMMENT ON COLUMN TB_IO_FUNDING.AMT IS '원금';
COMMENT ON COLUMN TB_IO_FUNDING.START_DT IS '시작일 - 통화국·지점 영업일';
COMMENT ON COLUMN TB_IO_FUNDING.MATURITY_DT IS '만기일 - 휴일이면 다음 영업일';
COMMENT ON COLUMN TB_IO_FUNDING.TENOR_DAYS IS '기간(일)';
