-- 휴일 캘린더 : 국가·결제시스템별 휴일. 인도 임시휴일(RBI/NI Act·주정부)은 수시 등록 후 영향 거래 재계산.
CREATE TABLE TB_HOLIDAY (
  CAL_CODE                 VARCHAR2(8) NOT NULL,
  HOL_DT                   DATE NOT NULL,
  HOL_NAME                 VARCHAR2(60) NOT NULL,
  TEMP_YN                  VARCHAR2(1) NOT NULL,
