COMMENT ON COLUMN TB_HOLIDAY.TEMP_YN IS '임시휴일';
COMMENT ON COLUMN TB_HOLIDAY.DECLARED_BY IS '공표기관 - RBI/UP 주정부/본점 공지';
COMMENT ON COLUMN TB_HOLIDAY.DECLARED_DT IS '공표일 - 임시휴일 공표일 - 영향 재계산 기준';
COMMENT ON COLUMN TB_HOLIDAY.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_HOLIDAY.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_HOLIDAY.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_HOLIDAY.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_HOLIDAY.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 휴일 차이 조정 : 본점 고객결제일과 지점 지급일 차이에 따른 이자를 건별 산출 → 흡수 또는 본지점 정산.
CREATE TABLE TB_IO_FLOAT_ADJ (
  ADJ_ID                   NUMBER(12) NOT NULL,
  IO_REF                   VARCHAR2(16) NOT NULL,
  CAUSE_CAL                VARCHAR2(8) NOT NULL,
  CAUSE_HOL_DT             DATE,
  HO_VALUE_DT              DATE NOT NULL,
  BR_VALUE_DT              DATE NOT NULL,
  DAYS                     NUMBER(4) NOT NULL,
  RATE_PCT                 NUMBER(9,6) NOT NULL,
  INT_AMT                  NUMBER(18,2) NOT NULL,
  TREAT                    VARCHAR2(6) NOT NULL,
  GL_CODE                  VARCHAR2(11),
  CUST_CLAIM_YN            VARCHAR2(1) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_IO_FLOAT_ADJ PRIMARY KEY (ADJ_ID)
);
COMMENT ON TABLE TB_IO_FLOAT_ADJ IS '휴일 차이 조정';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.ADJ_ID IS '조정ID';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.IO_REF IS '본지점 Ref';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.CAUSE_CAL IS '원인 캘린더 - IN/US/KR';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.CAUSE_HOL_DT IS '원인 휴일';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.HO_VALUE_DT IS '본점 결제일';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.BR_VALUE_DT IS '지점 결제일';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.DAYS IS '일수(±) - + 지점 선지급(지점 자금부담) / - 본점 선수취';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.RATE_PCT IS '적용금리 - TB_IO_RATE(INT) all-in';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.INT_AMT IS '이자 - AMT × RATE × DAYS / 일수기준';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.TREAT IS '처리 - ABSORB/SETTLE (IO_FLOAT_ABSORB_USD)';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.GL_CODE IS '계정 - SETTLE: 11010000000/40620000000, ABSORB: 분개 없음';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.CUST_CLAIM_YN IS '고객 청구 - 기본 N (휴일 차이는 고객에게 청구하지 않음)';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- Nostro 계좌(통화별) : 통화별 당행 결제계좌. 당발 경로 판정의 기준(Serial 수신은행, Cover의 InstgRmbrsmntAgt).
CREATE TABLE TB_NOSTRO_ACCT (
  CCY                      VARCHAR2(3) NOT NULL,
  NOSTRO_SEQ               NUMBER(2) NOT NULL,
  NOSTRO_BIC               VARCHAR2(11) NOT NULL,
  NOSTRO_ACCT              VARCHAR2(34) NOT NULL,
  HO_YN                    VARCHAR2(1) NOT NULL,
  GL_CODE                  VARCHAR2(11) NOT NULL,
  CUTOFF_IST               VARCHAR2(5) NOT NULL,
  SETTLE_CAL               VARCHAR2(4) NOT NULL,
  DEFAULT_YN               VARCHAR2(1) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_NOSTRO_ACCT PRIMARY KEY (CCY, NOSTRO_SEQ)
);
COMMENT ON TABLE TB_NOSTRO_ACCT IS 'Nostro 계좌(통화별)';
COMMENT ON COLUMN TB_NOSTRO_ACCT.CCY IS '통화';
COMMENT ON COLUMN TB_NOSTRO_ACCT.NOSTRO_SEQ IS '순번 - 1=기본';
COMMENT ON COLUMN TB_NOSTRO_ACCT.NOSTRO_BIC IS 'Nostro BIC';
COMMENT ON COLUMN TB_NOSTRO_ACCT.NOSTRO_ACCT IS '당행 계좌번호 - 예: 4001';
COMMENT ON COLUMN TB_NOSTRO_ACCT.HO_YN IS '본점 계좌 여부 - Y면 결제계정 21010000000(을A)';
COMMENT ON COLUMN TB_NOSTRO_ACCT.GL_CODE IS '계정 - 10105020000 (본점이면 21010000000)';
COMMENT ON COLUMN TB_NOSTRO_ACCT.CUTOFF_IST IS '당일결제 마감(IST) - 예: USD 16:30';
COMMENT ON COLUMN TB_NOSTRO_ACCT.SETTLE_CAL IS '결제통화 캘린더 - US/KR/TGT2 등 + IN';
COMMENT ON COLUMN TB_NOSTRO_ACCT.DEFAULT_YN IS '기본';
COMMENT ON COLUMN TB_NOSTRO_ACCT.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_NOSTRO_ACCT.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_NOSTRO_ACCT.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_NOSTRO_ACCT.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_NOSTRO_ACCT.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 은행 디렉터리·관계 : BIC별 은행 정보와 당행과의 관계(Nostro·본점·Vostro·RMA·고위험). SWIFTRef 일배치 + 지점 관계 속성.
CREATE TABLE TB_BIC_DIR (
  BIC                      VARCHAR2(11) NOT NULL,
  BANK_NAME                VARCHAR2(140) NOT NULL,
  TOWN                     VARCHAR2(35),
  CTRY                     VARCHAR2(2) NOT NULL,
  OWN_BANK_YN              VARCHAR2(1) NOT NULL,
  NOSTRO_CCY               VARCHAR2(20),
  VOSTRO_ACCT_NO           VARCHAR2(20),
  RMA_PAY_YN               VARCHAR2(1) NOT NULL,
  HIGH_RISK_YN             VARCHAR2(1) NOT NULL,
  CLR_CODE                 VARCHAR2(20),
  SRC                      VARCHAR2(10),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_BIC_DIR PRIMARY KEY (BIC)
);
COMMENT ON TABLE TB_BIC_DIR IS '은행 디렉터리·관계';
COMMENT ON COLUMN TB_BIC_DIR.BIC IS 'BIC';
COMMENT ON COLUMN TB_BIC_DIR.BANK_NAME IS '은행명';
COMMENT ON COLUMN TB_BIC_DIR.TOWN IS '도시';
COMMENT ON COLUMN TB_BIC_DIR.CTRY IS '국가';
COMMENT ON COLUMN TB_BIC_DIR.OWN_BANK_YN IS '당행(본점·점포) - Y면 DIRECT_HO 후보';
COMMENT ON COLUMN TB_BIC_DIR.NOSTRO_CCY IS '당행 Nostro 통화 - TB_NOSTRO_ACCT 역참조';
COMMENT ON COLUMN TB_BIC_DIR.VOSTRO_ACCT_NO IS '당행 보유 Vostro - 있으면 INR VOSTRO 후보';
COMMENT ON COLUMN TB_BIC_DIR.RMA_PAY_YN IS 'RMA(지급전문 송신) 승인 - TB_SWIFT_RMA 요약. N이면 직접 송신 불가';
COMMENT ON COLUMN TB_BIC_DIR.HIGH_RISK_YN IS '고위험국 - FATF·내부 국가위험';
COMMENT ON COLUMN TB_BIC_DIR.CLR_CODE IS '청산코드 - USABA/GBDSC/AUBSB 등 (BIC 없을 때)';
COMMENT ON COLUMN TB_BIC_DIR.SRC IS '출처 - SWIFTREF/MANUAL';
COMMENT ON COLUMN TB_BIC_DIR.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_BIC_DIR.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_BIC_DIR.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_BIC_DIR.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_BIC_DIR.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 수취은행 결제지시(SSI) : 수취은행이 통화별로 자금을 받는 코레스 은행·계좌. Cover의 InstdRmbrsmntAgt, Serial의 IntrmyAgt1.
CREATE TABLE TB_BANK_SSI (
  BIC                      VARCHAR2(11) NOT NULL,
  CCY                      VARCHAR2(3) NOT NULL,
  CORR_BIC                 VARCHAR2(11) NOT NULL,
  CORR_ACCT                VARCHAR2(34),
  VALID_FROM               DATE NOT NULL,
  SRC                      VARCHAR2(12) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_BANK_SSI PRIMARY KEY (BIC, CCY)
);
COMMENT ON TABLE TB_BANK_SSI IS '수취은행 결제지시(SSI)';
COMMENT ON COLUMN TB_BANK_SSI.BIC IS '수취은행 BIC';
COMMENT ON COLUMN TB_BANK_SSI.CCY IS '통화';
COMMENT ON COLUMN TB_BANK_SSI.CORR_BIC IS '코레스 BIC - 우리 Nostro와 같으면 Nostro 내 대체(중계 없음)';
COMMENT ON COLUMN TB_BANK_SSI.CORR_ACCT IS '수취은행 계좌(코레스)';
COMMENT ON COLUMN TB_BANK_SSI.VALID_FROM IS '적용시작';
COMMENT ON COLUMN TB_BANK_SSI.SRC IS '출처 - SWIFTREF_SSI/BILATERAL';
COMMENT ON COLUMN TB_BANK_SSI.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_BANK_SSI.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_BANK_SSI.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_BANK_SSI.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_BANK_SSI.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 당발 결제경로·전문 판정 : 송금별 경로 판정 결과(시스템 권장·최종·수동변경)와 생성 전문. SW11 송신 순서·대사의 기준.
CREATE TABLE TB_REMIT_ROUTE (
  REMIT_REF_NO             VARCHAR2(16) NOT NULL,
  SYS_METHOD               VARCHAR2(10) NOT NULL,
  FINAL_METHOD             VARCHAR2(10) NOT NULL,
  OVERRIDE_YN              VARCHAR2(1) NOT NULL,
  OVERRIDE_RSN             VARCHAR2(5),
  OVERRIDE_APPR_ID         VARCHAR2(10),
  DECISION_PATH            VARCHAR2(400) NOT NULL,
  STTLM_MTD                VARCHAR2(4) NOT NULL,
  NOSTRO_BIC               VARCHAR2(11),
  INSTD_AGT                VARCHAR2(11) NOT NULL,
  INTRMY_AGT1              VARCHAR2(11),
  CDTR_AGT                 VARCHAR2(11),
  CDTR_AGT_CLR             VARCHAR2(20),
  INSTG_RMB_AGT            VARCHAR2(11),
  INSTD_RMB_AGT            VARCHAR2(11),
  CHRG_BR                  VARCHAR2(4) NOT NULL,
  MSG_CUST_ID              VARCHAR2(20),
  MSG_COV_ID               VARCHAR2(20),
  UETR                     VARCHAR2(36) NOT NULL,
  SETTLE_GL                VARCHAR2(11) NOT NULL,
  VALUE_DT                 DATE NOT NULL,
  CUTOFF_MISS_YN           VARCHAR2(1) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_REMIT_ROUTE PRIMARY KEY (REMIT_REF_NO)
);
COMMENT ON TABLE TB_REMIT_ROUTE IS '당발 결제경로·전문 판정';
COMMENT ON COLUMN TB_REMIT_ROUTE.REMIT_REF_NO IS '송금참조번호';
COMMENT ON COLUMN TB_REMIT_ROUTE.SYS_METHOD IS '시스템 권장 - CODE:ROUTE_METHOD';
COMMENT ON COLUMN TB_REMIT_ROUTE.FINAL_METHOD IS '최종 경로 - CODE:ROUTE_METHOD';
COMMENT ON COLUMN TB_REMIT_ROUTE.OVERRIDE_YN IS '수동변경';
COMMENT ON COLUMN TB_REMIT_ROUTE.OVERRIDE_RSN IS '변경사유 - CODE:ROUTE_OVR_RSN, Y면 필수';
COMMENT ON COLUMN TB_REMIT_ROUTE.OVERRIDE_APPR_ID IS '변경 승인자 - Checker';
COMMENT ON COLUMN TB_REMIT_ROUTE.DECISION_PATH IS '판정 경로 - Q1~Q6 답과 근거 스냅샷';
COMMENT ON COLUMN TB_REMIT_ROUTE.STTLM_MTD IS '결제방식 - CODE:STTLM_MTD';
COMMENT ON COLUMN TB_REMIT_ROUTE.NOSTRO_BIC IS '사용 Nostro';
COMMENT ON COLUMN TB_REMIT_ROUTE.INSTD_AGT IS 'pacs.008 수신은행 - MT103 {2:} 수신';
COMMENT ON COLUMN TB_REMIT_ROUTE.INTRMY_AGT1 IS '중계은행 - :56a';
COMMENT ON COLUMN TB_REMIT_ROUTE.CDTR_AGT IS '수취은행 - :57a (BIC 또는 청산코드)';
COMMENT ON COLUMN TB_REMIT_ROUTE.CDTR_AGT_CLR IS '수취은행 청산코드';
COMMENT ON COLUMN TB_REMIT_ROUTE.INSTG_RMB_AGT IS 'InstgRmbrsmntAgt - Cover :53a = 당행 Nostro';
COMMENT ON COLUMN TB_REMIT_ROUTE.INSTD_RMB_AGT IS 'InstdRmbrsmntAgt - Cover :54a = 수취은행 코레스';
COMMENT ON COLUMN TB_REMIT_ROUTE.CHRG_BR IS '수수료부담 - DEBT/SHAR/CRED (:71A OUR/SHA/BEN)';
COMMENT ON COLUMN TB_REMIT_ROUTE.MSG_CUST_ID IS '고객송금 전문 - pacs.008';
COMMENT ON COLUMN TB_REMIT_ROUTE.MSG_COV_ID IS 'Cover 전문 - pacs.009 COV (같은 UETR)';
COMMENT ON COLUMN TB_REMIT_ROUTE.UETR IS 'UETR - gpi 추적, Cover와 공유';
COMMENT ON COLUMN TB_REMIT_ROUTE.SETTLE_GL IS '결제계정 - 10105020000 / 21010000000 / 20150200100·200';
COMMENT ON COLUMN TB_REMIT_ROUTE.VALUE_DT IS '결제일 - 마감시각·IN+통화 캘린더 반영';
COMMENT ON COLUMN TB_REMIT_ROUTE.CUTOFF_MISS_YN IS '마감 경과 - Y면 익영업일';
COMMENT ON COLUMN TB_REMIT_ROUTE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_REMIT_ROUTE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_REMIT_ROUTE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_REMIT_ROUTE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_REMIT_ROUTE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 계정과목(통합 표준 CoA) : 차세대 GBS 통합 표준 CoA(0930) + 인도지점 적용 상태. 모든 GL_CODE의 참조 마스터. 신규 계정은 본점 채번 전 임시코드.
CREATE TABLE TB_COA_ACCT (
  ACCT_CD                  VARCHAR2(11) NOT NULL,
  ACCT_LVL                 NUMBER(1) NOT NULL,
  PARENT_CD                VARCHAR2(11),
  ACCT_NM_EN               VARCHAR2(100) NOT NULL,
  ACCT_NM_BR               VARCHAR2(100),
  BS_PL                    VARCHAR2(10) NOT NULL,
  HO_ACCT_CD               VARCHAR2(13),
  GBS_CD                   VARCHAR2(8),
  NONMON_YN                VARCHAR2(1),
  POSTABLE_YN              VARCHAR2(1) NOT NULL,
  BR_STATUS                VARCHAR2(6),
  TEMP_CD_YN               VARCHAR2(1),
  BR_MEMO                  VARCHAR2(400),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_COA_ACCT PRIMARY KEY (ACCT_CD)
);
COMMENT ON TABLE TB_COA_ACCT IS '계정과목(통합 표준 CoA)';
COMMENT ON COLUMN TB_COA_ACCT.ACCT_CD IS '계정코드 - 11자리 Level1~6';
COMMENT ON COLUMN TB_COA_ACCT.ACCT_LVL IS '레벨 - 1~6';
COMMENT ON COLUMN TB_COA_ACCT.PARENT_CD IS '상위계정';
COMMENT ON COLUMN TB_COA_ACCT.ACCT_NM_EN IS '계정명(영문)';
COMMENT ON COLUMN TB_COA_ACCT.ACCT_NM_BR IS '인도지점 표시명 - 예: STATE BANK → RESERVE BANK OF INDIA';
COMMENT ON COLUMN TB_COA_ACCT.BS_PL IS '구분 - 자산/부채/자본/수익/비용/각주(난외)';
COMMENT ON COLUMN TB_COA_ACCT.HO_ACCT_CD IS '본점 통합계정';
COMMENT ON COLUMN TB_COA_ACCT.GBS_CD IS '현행 GBS 코드 - 이행 매핑';
COMMENT ON COLUMN TB_COA_ACCT.NONMON_YN IS '비화폐성 - 외화환산 제외';
COMMENT ON COLUMN TB_COA_ACCT.POSTABLE_YN IS '기장 가능 - 하위 L5가 있는 계정은 N(직접 기장 금지)';
COMMENT ON COLUMN TB_COA_ACCT.BR_STATUS IS '인도지점 상태 - NEW(신규·임시코드)/MOD(변경)/INACT(비활성)';
COMMENT ON COLUMN TB_COA_ACCT.TEMP_CD_YN IS '임시코드 - 본점 채번 후 ACCT_CD 교체, 이력은 TB_ACCT_RULE 동시 갱신';
COMMENT ON COLUMN TB_COA_ACCT.BR_MEMO IS '메모';
COMMENT ON COLUMN TB_COA_ACCT.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_COA_ACCT.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_COA_ACCT.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_COA_ACCT.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_COA_ACCT.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 업무별 분개 규칙 : 업무 이벤트별 차대 계정과 금액기준. 송금·환전·FDI·Vostro·본지점·무역금융 화면은 이 규칙으로 분개를 생성(CM-CMGL 연동).
CREATE TABLE TB_ACCT_RULE (
  EVENT_CD                 VARCHAR2(12) NOT NULL,
  LEG_SEQ                  NUMBER(3) NOT NULL,
  DC                       VARCHAR2(3) NOT NULL,
  ACCT_CD                  VARCHAR2(11) NOT NULL,
  CCY_BASIS                VARCHAR2(3) NOT NULL,
  AMT_BASIS                VARCHAR2(12) NOT NULL,
  SCREEN_ID                VARCHAR2(20),
  EVENT_DESC               VARCHAR2(200),
  EFF_FROM_DT              DATE NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_ACCT_RULE PRIMARY KEY (EVENT_CD, LEG_SEQ)
);
COMMENT ON TABLE TB_ACCT_RULE IS '업무별 분개 규칙';
COMMENT ON COLUMN TB_ACCT_RULE.EVENT_CD IS '이벤트 - 예: OUT-01-①';
COMMENT ON COLUMN TB_ACCT_RULE.LEG_SEQ IS '순번';
COMMENT ON COLUMN TB_ACCT_RULE.DC IS '차대 - D/C/OB+/OB-';
COMMENT ON COLUMN TB_ACCT_RULE.ACCT_CD IS '계정 - TB_COA_ACCT, POSTABLE_YN=Y·비활성 아님';
COMMENT ON COLUMN TB_ACCT_RULE.CCY_BASIS IS '통화기준 - INR / FCY(거래통화)';
COMMENT ON COLUMN TB_ACCT_RULE.AMT_BASIS IS '금액기준 - FCY_AMT/INR_AMT/COMM/CABLE/CGST/SGST/IGST/TCS/NET_CR/TOTAL_DR/DISC_INT/FACE/...';
COMMENT ON COLUMN TB_ACCT_RULE.SCREEN_ID IS '화면';
COMMENT ON COLUMN TB_ACCT_RULE.EVENT_DESC IS '설명';
COMMENT ON COLUMN TB_ACCT_RULE.EFF_FROM_DT IS '적용시작';
COMMENT ON COLUMN TB_ACCT_RULE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_ACCT_RULE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_ACCT_RULE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_ACCT_RULE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_ACCT_RULE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 송금·환전 시뮬레이션(견적) : 송금·환전 전 예상 환율·환전액·수수료·GST·TCS를 계산한 견적. 실거래 전환 시 원거래와 연결.
CREATE TABLE TB_FX_SIMULATION (
  QUOTE_ID                 VARCHAR2(16) NOT NULL,
  SIM_TYPE                 VARCHAR2(8) NOT NULL,
  CUST_NO                  VARCHAR2(8),
  CCY                      VARCHAR2(3) NOT NULL,
  INPUT_BASIS              VARCHAR2(3) NOT NULL,
  INPUT_AMT                NUMBER(18,2) NOT NULL,
  RATE_SRC                 VARCHAR2(4) NOT NULL,
  RATE_CARD_SEQ            NUMBER(3),
  APPLIED_RATE             NUMBER(15,6) NOT NULL,
  FCY_AMT                  NUMBER(18,2) NOT NULL,
  INR_AMT                  NUMBER(18,2) NOT NULL,
  FEE_AMT                  NUMBER(18,2) NOT NULL,
  GST_FX_VALUE             NUMBER(18,2),
  GST_AMT                  NUMBER(18,2) NOT NULL,
  TCS_AMT                  NUMBER(18,2),
  TOTAL_DEBIT              NUMBER(18,2),
  NET_CREDIT               NUMBER(18,2),
  EXCESS_FCY               NUMBER(18,2),
  VALID_UNTIL              TIMESTAMP NOT NULL,
  CONVERTED_REF            VARCHAR2(16),
  QUOTE_STS                VARCHAR2(5) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_SIMULATION PRIMARY KEY (QUOTE_ID)
);
COMMENT ON TABLE TB_FX_SIMULATION IS '송금·환전 시뮬레이션(견적)';
COMMENT ON COLUMN TB_FX_SIMULATION.QUOTE_ID IS '견적번호 - Q+YYMMDD+일련';
COMMENT ON COLUMN TB_FX_SIMULATION.SIM_TYPE IS '유형 - OUT_GEN/OUT_LRS/OUT_TRD/OUT_NR/IN_GEN/IN_FDI/FX_ACCT/FX_CASH';
COMMENT ON COLUMN TB_FX_SIMULATION.CUST_NO IS '고객번호 - 비계좌 견적은 NULL';
COMMENT ON COLUMN TB_FX_SIMULATION.CCY IS '통화';
COMMENT ON COLUMN TB_FX_SIMULATION.INPUT_BASIS IS '입력 기준 - FCY 금액 / INR 금액(INR 확정)';
COMMENT ON COLUMN TB_FX_SIMULATION.INPUT_AMT IS '입력 금액';
COMMENT ON COLUMN TB_FX_SIMULATION.RATE_SRC IS '환율 출처 - CARD(회차) / DEAL(자금팀 견적)';
COMMENT ON COLUMN TB_FX_SIMULATION.RATE_CARD_SEQ IS '고시 회차';
COMMENT ON COLUMN TB_FX_SIMULATION.APPLIED_RATE IS '적용 환율';
COMMENT ON COLUMN TB_FX_SIMULATION.FCY_AMT IS '외화 금액';
COMMENT ON COLUMN TB_FX_SIMULATION.INR_AMT IS 'INR 금액';
COMMENT ON COLUMN TB_FX_SIMULATION.FEE_AMT IS '수수료 합계';
COMMENT ON COLUMN TB_FX_SIMULATION.GST_FX_VALUE IS '환전 과세표준 - 32(2)(b)';
COMMENT ON COLUMN TB_FX_SIMULATION.GST_AMT IS 'GST 합계 - CGST/SGST 또는 IGST, R-GST';
COMMENT ON COLUMN TB_FX_SIMULATION.TCS_AMT IS 'TCS - LRS';
COMMENT ON COLUMN TB_FX_SIMULATION.TOTAL_DEBIT IS '총 출금(당발)';
COMMENT ON COLUMN TB_FX_SIMULATION.NET_CREDIT IS '순 입금(타발)';
COMMENT ON COLUMN TB_FX_SIMULATION.EXCESS_FCY IS 'FDI 초과(반환 예정) - IN_FDI';
COMMENT ON COLUMN TB_FX_SIMULATION.VALID_UNTIL IS '유효시각 - 생성 + SIM_QUOTE_VALID_MIN, 회차 변경 시 만료';
COMMENT ON COLUMN TB_FX_SIMULATION.CONVERTED_REF IS '전환 거래 - 실거래 송금·환전 Ref';
COMMENT ON COLUMN TB_FX_SIMULATION.QUOTE_STS IS '상태 - OPEN/USED/EXPD';
COMMENT ON COLUMN TB_FX_SIMULATION.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_SIMULATION.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_SIMULATION.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_SIMULATION.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_SIMULATION.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 확인서·증명서 발급이력 : FIRC(FM-FDI-01)·당발확인서(FM-OUT-01)·타발확인서(FM-IN-01) 발급/재발급/정정 이력. 원본은 원천 1건당 1회.
CREATE TABLE TB_FX_ADVICE_ISSUE (
  ISSUE_NO                 VARCHAR2(30) NOT NULL,
  FORM_ID                  VARCHAR2(10) NOT NULL,
  SRC_TABLE                VARCHAR2(30) NOT NULL,
  SRC_KEY                  VARCHAR2(40) NOT NULL,
  CUST_NO                  VARCHAR2(8) NOT NULL,
  ISSUE_TYPE               VARCHAR2(3) NOT NULL,
  ORG_ISSUE_NO             VARCHAR2(30),
  ISSUE_SEQ                NUMBER(3) NOT NULL,
  ISSUE_DT                 DATE NOT NULL,
  ISSUE_RSN                VARCHAR2(200),
  DELIVERY                 VARCHAR2(4) NOT NULL,
  VERIFY_CODE              VARCHAR2(16) NOT NULL,
  SNAPSHOT_JSON            CLOB NOT NULL,
  DMS_KEY                  VARCHAR2(64),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_ADVICE_ISSUE PRIMARY KEY (ISSUE_NO)
);
COMMENT ON TABLE TB_FX_ADVICE_ISSUE IS '확인서·증명서 발급이력';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_NO IS '발급번호 - 서식약어/지점/FY/일련 (예: FIRC/NOI/2026-27/000041)';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.FORM_ID IS '서식ID - FM-FDI-01 / FM-OUT-01 / FM-IN-01';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SRC_TABLE IS '원천테이블 - TB_FDI_INFLOW / TB_FX_REMIT_MST';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SRC_KEY IS '원천키 - FDI_REF_NO 또는 REMIT_REF_NO';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.CUST_NO IS '고객번호';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_TYPE IS '발급구분 - ORG원본/DUP재발급/AMD정정/CXL취소';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ORG_ISSUE_NO IS '원본 발급번호 - DUP/AMD/CXL 시 필수';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_SEQ IS '발급차수 - 원본=1, 재발급마다 +1';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_DT IS '발급일';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_RSN IS '재발급/정정 사유';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.DELIVERY IS '전달방식 - PRNT창구출력/MAIL/INET인터넷뱅킹';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.VERIFY_CODE IS '진위확인코드 - HMAC(발급번호+금액+일자) 앞 16자리, QR 표시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SNAPSHOT_JSON IS '발급내용 스냅샷 - 발급 시점 표기값 전체 - 재발급은 이 값으로 동일 재현';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.DMS_KEY IS 'PDF 보관키';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_FX_ADVICE_ISSUE_1 ON TB_FX_ADVICE_ISSUE (SRC_TABLE,SRC_KEY);
CREATE INDEX IX_FX_ADVICE_ISSUE_2 ON TB_FX_ADVICE_ISSUE (CUST_NO,ISSUE_DT);

-- 무역금융 거래(BILL_MASTER) : 어음할인·매입·LC 매입·D/A·D/P 추심·오픈어카운트·TReDS 통합 원장. 거래유형별 하위 테이블 1:1.
CREATE TABLE TB_TF_BILL (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  BILL_CATEGORY            VARCHAR2(14) NOT NULL,
  BILL_TYPE                VARCHAR2(14) NOT NULL,
  DIRECTION                VARCHAR2(6) NOT NULL,
  CUST_NO                  VARCHAR2(8) NOT NULL,
  DRAWER_NAME              VARCHAR2(140) NOT NULL,
  DRAWEE_NAME              VARCHAR2(140) NOT NULL,
  DRAWEE_CTRY              VARCHAR2(2),
  COUNTERPARTY_BANK_BIC    VARCHAR2(11),
  LC_REF                   VARCHAR2(16),
  CCY                      VARCHAR2(3) NOT NULL,
  BILL_AMT                 NUMBER(18,2) NOT NULL,
  FX_RATE                  NUMBER(15,6),
  INR_EQV                  NUMBER(18,2) NOT NULL,
  BILL_DT                  DATE NOT NULL,
  TENOR_DAYS               NUMBER(4),
  DUE_DT                   DATE,
  SHIPMENT_DT              DATE,
  REALIZE_DUE_DT           DATE,
  SB_MGMT_NO               VARCHAR2(16),
  BOE_MGMT_NO              VARCHAR2(16),
  HS_CODE                  VARCHAR2(8),
  PURPOSE_CODE             VARCHAR2(5),
  ECGC_COVER_YN            VARCHAR2(1),
  PSL_CAT                  VARCHAR2(10),
  BILL_STS                 VARCHAR2(10) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  AUTH_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_TF_BILL PRIMARY KEY (BILL_REF)
);
COMMENT ON TABLE TB_TF_BILL IS '무역금융 거래(BILL_MASTER)';
COMMENT ON COLUMN TB_TF_BILL.BILL_REF IS '어음참조번호 - BR-지점-YYMMDD-일련 / TReDS는 TR-플랫폼-YYMMDD-일련. SFMS E2E ID로 사용(35자 이내)';
COMMENT ON COLUMN TB_TF_BILL.BILL_CATEGORY IS '거래유형 - CODE:BILL_CATEGORY';
COMMENT ON COLUMN TB_TF_BILL.BILL_TYPE IS '어음유형 - EXPORT_USANCE/EXPORT_SIGHT/IMPORT_USANCE/IMPORT_SIGHT/INLAND_DEMAND/INLAND_USANCE/CLEAN';
COMMENT ON COLUMN TB_TF_BILL.DIRECTION IS '무역방향 - EXPORT/IMPORT/INLAND';
COMMENT ON COLUMN TB_TF_BILL.CUST_NO IS '고객번호 - 한도·여신 심사 대상(수출자/수입자)';
COMMENT ON COLUMN TB_TF_BILL.DRAWER_NAME IS '발행인';
COMMENT ON COLUMN TB_TF_BILL.DRAWEE_NAME IS '지급인';
COMMENT ON COLUMN TB_TF_BILL.DRAWEE_CTRY IS '지급인 국가 - 국가한도·국가 프리미엄';
COMMENT ON COLUMN TB_TF_BILL.COUNTERPARTY_BANK_BIC IS '추심·개설은행 - LC 매입은 개설은행(신용 프리미엄 평가 대상)';
COMMENT ON COLUMN TB_TF_BILL.LC_REF IS '신용장 참조 - LC 기반 매입(NEGOTIATION)·인수';
COMMENT ON COLUMN TB_TF_BILL.CCY IS '통화';
COMMENT ON COLUMN TB_TF_BILL.BILL_AMT IS '어음금액';
COMMENT ON COLUMN TB_TF_BILL.FX_RATE IS '적용환율 - FEDAI 고시 대비 편차 검증';
COMMENT ON COLUMN TB_TF_BILL.INR_EQV IS 'INR 환산';
COMMENT ON COLUMN TB_TF_BILL.BILL_DT IS '어음일자';
COMMENT ON COLUMN TB_TF_BILL.TENOR_DAYS IS '만기일수';
COMMENT ON COLUMN TB_TF_BILL.DUE_DT IS '만기일 - 휴일이면 영업일 조정(R-HOL-01)';
COMMENT ON COLUMN TB_TF_BILL.SHIPMENT_DT IS '선적일 - 회수기한·유전스 기산';
COMMENT ON COLUMN TB_TF_BILL.REALIZE_DUE_DT IS '회수기한 - 수출: 선적일 + TF_EXP_REALIZE_MONTHS';
COMMENT ON COLUMN TB_TF_BILL.SB_MGMT_NO IS 'Shipping Bill - 수출 - TB_TRD_SHIPPING_BILL 연결(EDPMS)';
COMMENT ON COLUMN TB_TF_BILL.BOE_MGMT_NO IS 'Bill of Entry - 수입 - TB_TRD_BOE 연결(IDPMS)';
COMMENT ON COLUMN TB_TF_BILL.HS_CODE IS 'HS Code - 수입 유전스 상한(자본재 여부) 판정';
COMMENT ON COLUMN TB_TF_BILL.PURPOSE_CODE IS 'Purpose';
COMMENT ON COLUMN TB_TF_BILL.ECGC_COVER_YN IS 'ECGC 부보 - 리스크 프리미엄 차등';
COMMENT ON COLUMN TB_TF_BILL.PSL_CAT IS '우선대출 분류 - EXPORT/MSME/NONE (TReDS MSME 자동)';
COMMENT ON COLUMN TB_TF_BILL.BILL_STS IS '상태 - DRAFT/SUBMIT/APPROVED/DISBURSED/MATURED/OVERDUE/REALIZED/CRYSTAL/NPA/CLOSED/CANCEL';
COMMENT ON COLUMN TB_TF_BILL.REG_USER_ID IS '등록자(Maker)';
COMMENT ON COLUMN TB_TF_BILL.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_TF_BILL.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_TF_BILL.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_TF_BILL.APPR_USER_ID IS '승인자(Checker) - Maker와 동일인 불가';
COMMENT ON COLUMN TB_TF_BILL.AUTH_USER_ID IS 'Authorizer - ALCO 기준금액 초과 시';
CREATE INDEX IX_TF_BILL_1 ON TB_TF_BILL (CUST_NO,BILL_STS);
CREATE INDEX IX_TF_BILL_2 ON TB_TF_BILL (DUE_DT);
CREATE INDEX IX_TF_BILL_3 ON TB_TF_BILL (LC_REF);

-- 선적서류 : B/L·Invoice·P/L·보험·S/B 등 서류 체크리스트(오픈어카운트는 선택).
CREATE TABLE TB_TF_DOC (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  SEQ                      NUMBER(3) NOT NULL,
  DOC_TYPE                 VARCHAR2(6) NOT NULL,
  DOC_NO                   VARCHAR2(35),
  DOC_DT                   DATE,
  ORIG_CNT                 NUMBER(2),
  COPY_CNT                 NUMBER(2),
  DOC_STS                  VARCHAR2(6) NOT NULL,
  CONSTRAINT PK_TF_DOC PRIMARY KEY (BILL_REF, SEQ)
);
COMMENT ON TABLE TB_TF_DOC IS '선적서류';
COMMENT ON COLUMN TB_TF_DOC.BILL_REF IS '어음참조번호';
COMMENT ON COLUMN TB_TF_DOC.SEQ IS '순번';
COMMENT ON COLUMN TB_TF_DOC.DOC_TYPE IS '서류유형 - BL/AWB/INV/PL/INS/SB/BOE/COO/BOX';
COMMENT ON COLUMN TB_TF_DOC.DOC_NO IS '서류번호';
COMMENT ON COLUMN TB_TF_DOC.DOC_DT IS '서류일자';
COMMENT ON COLUMN TB_TF_DOC.ORIG_CNT IS '원본 수';
COMMENT ON COLUMN TB_TF_DOC.COPY_CNT IS '사본 수';
COMMENT ON COLUMN TB_TF_DOC.DOC_STS IS '상태 - RCVD/CHKD/MISS/DISC(하자)';

-- 할인계산 : 기준금리·기간스프레드·신용·국가·정책 프리미엄 5단계와 공제액·순지급액. 산출 근거 전부 저장.
CREATE TABLE TB_TF_DISCOUNT (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  RATE_TYPE                VARCHAR2(6) NOT NULL,
  BASE_SRC                 VARCHAR2(20) NOT NULL,
  BASE_RATE                NUMBER(9,6) NOT NULL,
  TENOR_SPREAD             NUMBER(9,6) NOT NULL,
  CREDIT_PREM              NUMBER(9,6) NOT NULL,
  ISSUER_GRADE             VARCHAR2(1),
  COUNTRY_PREM             NUMBER(9,6) NOT NULL,
  POLICY_PREM              NUMBER(9,6) NOT NULL,
  EFF_RATE                 NUMBER(9,6) NOT NULL,
  DAYCOUNT                 VARCHAR2(8) NOT NULL,
  DISC_DAYS                NUMBER(4) NOT NULL,
  DISC_AMT                 NUMBER(18,2) NOT NULL,
  COMMISSION               NUMBER(18,2) NOT NULL,
  GST_AMT                  NUMBER(18,2) NOT NULL,
  MSG_CHG                  NUMBER(18,2),
  NET_PROCEEDS             NUMBER(18,2) NOT NULL,
  DISC_PCT                 NUMBER(7,4),
  TOTAL_DED_PCT            NUMBER(7,4),
  NET_PCT                  NUMBER(7,4),
  INCOME_RECOG             VARCHAR2(7) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  AUTH_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_TF_DISCOUNT PRIMARY KEY (BILL_REF)
);
COMMENT ON TABLE TB_TF_DISCOUNT IS '할인계산';
COMMENT ON COLUMN TB_TF_DISCOUNT.BILL_REF IS '어음참조번호';
COMMENT ON COLUMN TB_TF_DISCOUNT.RATE_TYPE IS '금리유형 - MCLR/EBLR/SOFR/EURIBOR/FIXED';
COMMENT ON COLUMN TB_TF_DISCOUNT.BASE_SRC IS '기준금리 출처 - INR: MCLR 1년물(또는 EBLR) / FCY: SOFR·EURIBOR + 조달마진';
COMMENT ON COLUMN TB_TF_DISCOUNT.BASE_RATE IS '① 기준금리 - 적용 하한(R-TF-12)';
COMMENT ON COLUMN TB_TF_DISCOUNT.TENOR_SPREAD IS '② 기간 스프레드 - ≤90일 0.25 / 91~180 0.50 / >180 0.85 (ALCO)';
COMMENT ON COLUMN TB_TF_DISCOUNT.CREDIT_PREM IS '③ 신용 프리미엄 - LC: 개설은행 등급 / 그 외: 지급인·수출자 등급';
COMMENT ON COLUMN TB_TF_DISCOUNT.ISSUER_GRADE IS '개설은행 등급 - S/A/B/C/D/E (TB_TF_ISSUER_EVAL)';
COMMENT ON COLUMN TB_TF_DISCOUNT.COUNTRY_PREM IS '④ 국가 프리미엄 - OECD CRC 0~7';
COMMENT ON COLUMN TB_TF_DISCOUNT.POLICY_PREM IS '⑤ 정책 프리미엄 - -0.50 ~ +1.00, 결재선 차등(TB_TF_POLICY_ADJ)';
COMMENT ON COLUMN TB_TF_DISCOUNT.EFF_RATE IS '적용금리 - = ①+②+③+④+⑤, 하한·상한 검증';
COMMENT ON COLUMN TB_TF_DISCOUNT.DAYCOUNT IS '일수기준 - INR ACT/365, FCY ACT/360 (관리자 변경 가능)';
COMMENT ON COLUMN TB_TF_DISCOUNT.DISC_DAYS IS '할인일수';
COMMENT ON COLUMN TB_TF_DISCOUNT.DISC_AMT IS '할인료 - = 액면 × 적용금리 × 일수 / 일수기준';
COMMENT ON COLUMN TB_TF_DISCOUNT.COMMISSION IS '취급수수료';
COMMENT ON COLUMN TB_TF_DISCOUNT.GST_AMT IS 'GST - 수수료·전신료 과세(R-GST-*). 할인료(이자)는 비과세';
COMMENT ON COLUMN TB_TF_DISCOUNT.MSG_CHG IS '전신료 - SWIFT/SFMS';
COMMENT ON COLUMN TB_TF_DISCOUNT.NET_PROCEEDS IS '순지급액 - = 액면 - 할인료 - 수수료 - GST - 전신료 → A/P 계상';
COMMENT ON COLUMN TB_TF_DISCOUNT.DISC_PCT IS '할인비율';
