-- 개설은행 평가 : 개설은행 3축(바젤III 40·외부등급 35·거래이력 25) 100점 → S~E 등급. 반기 재평가 + 이벤트 재평가.
CREATE TABLE TB_TF_ISSUER_EVAL (
  BANK_BIC                 VARCHAR2(11) NOT NULL,
  EVAL_DT                  DATE NOT NULL,
  BANK_CTRY                VARCHAR2(2) NOT NULL,
  AX1_SCORE                NUMBER(5,2),
  AX2_SCORE                NUMBER(5,2),
  AX3_SCORE                NUMBER(5,2),
  REFUSAL_CNT_24M          NUMBER(4),
  TOTAL_SCORE              NUMBER(5,2) NOT NULL,
  GRADE                    VARCHAR2(1) NOT NULL,
  BASE_PREMIUM             NUMBER(6,4),
  SINGLE_BANK_CAP_PCT      NUMBER(5,2),
  NEXT_EVAL_DT             DATE NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  AUTH_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_TF_ISSUER_EVAL PRIMARY KEY (BANK_BIC, EVAL_DT)
);
COMMENT ON TABLE TB_TF_ISSUER_EVAL IS '개설은행 평가';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.BANK_BIC IS '개설은행 BIC';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.EVAL_DT IS '평가일';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.BANK_CTRY IS '소재국';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.AX1_SCORE IS '제1축 재무건전성 - CRAR·CET1·NPL·LCR·NSFR·레버리지 (Pillar 3). 자료 없으면 0, 제2축 55%로 상향';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.AX2_SCORE IS '제2축 외부등급 - Moody''s/S&P/Fitch/CRISIL, 국가등급 상한';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.AX3_SCORE IS '제3축 당행 거래이력 - 최근 24개월 승인불가(IFN/MT 734)·지급지연·분쟁 자동집계';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.REFUSAL_CNT_24M IS '거절(734) 건수 - TB_TF_LC_PRES·TB_SFMS_MSG(IFN 734)에서 자동';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.TOTAL_SCORE IS '종합점수';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.GRADE IS '등급 - S≥90 / A≥75 / B≥60 / C≥45 / D≥30 / E<30';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.BASE_PREMIUM IS '기본 프리미엄 - S 0.15 / A 0.35 / B 0.60 / C 1.00 / D 1.75 / E 취급불가';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.SINGLE_BANK_CAP_PCT IS '단일은행 상한(기본자본 %) - S 10 / A 8 / B 5 / C 3 / D 1 / E 0';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.NEXT_EVAL_DT IS '차기 평가일 - 반기. 등급 변동·부도·국가등급 하향 시 즉시';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.REG_USER_ID IS '등록자(Maker)';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.APPR_USER_ID IS '승인자(Checker) - Maker와 동일인 불가';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.AUTH_USER_ID IS 'Authorizer - ALCO 기준금액 초과 시';

-- 정책 프리미엄 조정 이력 : 재량 조정의 조정 전후·사유·결재선. 변경 불가 이력 10년 보존.
