COMMENT ON COLUMN TB_AP_ITEM.SRC_REF IS '원천 Ref - BILL_REF / SUSP_NO';
COMMENT ON COLUMN TB_AP_ITEM.GL_CODE IS '계정 - AP_TYPE별 통합 CoA 계정';
COMMENT ON COLUMN TB_AP_ITEM.CCY IS '통화';
