COMMENT ON COLUMN TB_BG_CLAIM.APPR_USER_ID IS '승인자(Checker) - Maker와 동일인 불가';
COMMENT ON COLUMN TB_BG_CLAIM.AUTH_USER_ID IS 'Authorizer - ALCO 기준금액 초과 시';

-- 자산건전성 일별 : 연체일수(DPD) → SMA-0/1/2·NPA, 충당금, CRILC 보고 대상.
CREATE TABLE TB_TF_ASSET_CLASS (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  AS_OF_DT                 DATE NOT NULL,
  DPD                      NUMBER(5) NOT NULL,
  ASSET_CLASS              VARCHAR2(6) NOT NULL,
  BORROWER_EXPOSURE_INR    NUMBER(18,2),
  CRILC_RPT_YN             VARCHAR2(1),
  PROVISION_AMT            NUMBER(18,2),
  INCOME_STOP_YN           VARCHAR2(1),
  CONSTRAINT PK_TF_ASSET_CLASS PRIMARY KEY (BILL_REF, AS_OF_DT)
);
COMMENT ON TABLE TB_TF_ASSET_CLASS IS '자산건전성 일별';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.BILL_REF IS '거래 Ref - BILL·LC 인수·BG 대지급';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.AS_OF_DT IS '기준일';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.DPD IS '연체일수';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.ASSET_CLASS IS '분류 - STD/SMA0/SMA1/SMA2/NPA';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.BORROWER_EXPOSURE_INR IS '차주 총익스포저 - CRILC 기준(₹5 crore 이상) 판정';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.CRILC_RPT_YN IS 'CRILC 보고 대상';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.PROVISION_AMT IS '충당금';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.INCOME_STOP_YN IS '이자인식 중단 - NPA';

-- 외화 어음 결정(Crystallisation) : 만기 후 미회수 외화 수출어음을 FEDAI 규칙에 따라 INR 채권으로 전환.
CREATE TABLE TB_TF_CRYSTAL (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  CRYSTAL_DT               DATE NOT NULL,
  TT_SELL_RATE             NUMBER(15,6) NOT NULL,
  INR_AMT                  NUMBER(18,2) NOT NULL,
  FX_POS_GL                VARCHAR2(11) NOT NULL,
  CONSTRAINT PK_TF_CRYSTAL PRIMARY KEY (BILL_REF)
);
COMMENT ON TABLE TB_TF_CRYSTAL IS '외화 어음 결정(Crystallisation)';
COMMENT ON COLUMN TB_TF_CRYSTAL.BILL_REF IS '어음참조번호';
COMMENT ON COLUMN TB_TF_CRYSTAL.CRYSTAL_DT IS '결정일 - 만기 + 30일 (FEDAI)';
COMMENT ON COLUMN TB_TF_CRYSTAL.TT_SELL_RATE IS '전신환매도율';
COMMENT ON COLUMN TB_TF_CRYSTAL.INR_AMT IS '결정 INR';
COMMENT ON COLUMN TB_TF_CRYSTAL.FX_POS_GL IS '환포지션 - 11200000000 (통화별 포지션)';

